package findu.backend.verification.entity; import findu.backend.founditem.entity.FoundItem; import findu.backend.global.entity.BaseEntity; import jakarta.persistence.*; import lombok.*; @Entity @Getter @Builder @NoArgsConstructor(access=AccessLevel.PROTECTED) @AllArgsConstructor @Table(name="verification_questions") public class VerificationQuestion extends BaseEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="found_item_id")FoundItem foundItem;@Column(nullable=false,length=255)String question;@Column(nullable=false,length=1000)String answerHash;}
